async start(): Promise<void> {
  this.stopped = false;
  if (this.config.path) {
    await this.load();
    // Reclaim spool files no surviving record points at.
    await this.sweepOrphanedSpool();
  }
  this.pump();
}

stop(): void {
  this.stopped = true;
  if (this.retryTimer) clearTimeout(this.retryTimer);
  this.retryTimer = undefined;
  if (this.persistRetryTimer) clearTimeout(this.persistRetryTimer);
  this.persistRetryTimer = undefined;
}

const spooled = await this.spoolAttachments(id, message);
await previousPreparation;
let record: DeliveryRecord | undefined;
try {
  await this.withMutation(async () => {
    try {
      if (this.stopped) throw new Error("Chat Gateway inbox is stopped");
      const persistent = Boolean(
        this.config.path && (!message.attachments?.length || spooled !== undefined),
      );
      const safeMessage = persistent
        ? serializableMessage(message, this.rehydrateAttachments(spooled))
        : message;
      record = {
        id,
        ...(dedupeKey ? { dedupeKey } : {}),
        adapterId,
        message: safeMessage,
        attempts: 0,
        nextAttemptAt: Date.now(),
        persistent,
        ...(spooled ? { spooled } : {}),
      };
      this.pending.push(record);
      if (persistent) await this.persist();
    } catch (error) {
      if (record) {
        const index = this.pending.findIndex((candidate) => candidate.id === record?.id);
        if (index >= 0) this.pending.splice(index, 1);
      }
      throw error;
    } finally {
      this.preparing.delete(id);
    }
  });
} catch (error) {
  await this.discardSpool(
    record ?? {
      id,
      adapterId,
      message,
      attempts: 0,
      nextAttemptAt: 0,
      persistent: false,
      ...(spooled ? { spooled } : {}),
    },
  );
  throw error;
} finally {
  releasePreparation?.();
  if (this.preparationByTarget.get(target) === preparation) {
    this.preparationByTarget.delete(target);
  }
}
this.pump();
return "queued";

private pump(): void {
  if (this.stopped) return;
  if (this.retryTimer) clearTimeout(this.retryTimer);
  this.retryTimer = undefined;
  const now = Date.now();
  while (this.inFlight.size < this.config.maxConcurrent) {
    const entry = this.pending.find((candidate) => {
      if (this.inFlight.has(candidate.id) || candidate.nextAttemptAt > now) return false;
      return (
        (this.targetInFlight.get(targetKey(candidate.message)) ?? 0) < this.config.maxPerTarget
      );
    });
    if (!entry) break;
    this.inFlight.add(entry.id);
    const key = targetKey(entry.message);
    this.targetInFlight.set(key, (this.targetInFlight.get(key) ?? 0) + 1);
    void this.process(entry);
  }
  const next = this.pending
    .filter((entry) => !this.inFlight.has(entry.id) && entry.nextAttemptAt > now)
    .reduce<
      number | undefined
    >((earliest, entry) => (earliest === undefined ? entry.nextAttemptAt : Math.min(earliest, entry.nextAttemptAt)), undefined);
  if (next !== undefined) {
    this.retryTimer = setTimeout(() => this.pump(), Math.max(1, next - Date.now()));
    this.retryTimer.unref?.();
  }
}

private async process(entry: DeliveryRecord): Promise<void> {
  let error: unknown;
  try {
    await this.deliver(entry.adapterId, entry.message);
  } catch (caught) {
    error = caught;
    this.onError(caught, entry.message);
  }

  const terminal = error === undefined || error instanceof UnroutableDeliveryError;
  try {
    await this.withMutation(async () => {
      this.inFlight.delete(entry.id);
      const key = targetKey(entry.message);
      const targetCount = (this.targetInFlight.get(key) ?? 1) - 1;
      if (targetCount <= 0) this.targetInFlight.delete(key);
      else this.targetInFlight.set(key, targetCount);

      if (terminal) {
        // Success, or a permanently unroutable record: drop it so a message
        // that can never be delivered does not retry (and re-log) forever.
        const index = this.pending.findIndex((candidate) => candidate.id === entry.id);
        if (index >= 0) this.pending.splice(index, 1);
        if (error === undefined && entry.dedupeKey)
          this.completed.set(entry.dedupeKey, Date.now());
      } else {
        entry.attempts += 1;
        entry.nextAttemptAt =
          Date.now() +
          Math.min(
            this.config.retryMaxMs,
            this.config.retryBaseMs * 2 ** Math.min(entry.attempts - 1, 10),
          );
      }
      this.pruneCompleted();
      // Persist the terminal removal BEFORE deleting attachment bytes. If the
      // state write fails, the durable record still has everything needed for
      // at-least-once recovery after a crash.
      if (entry.persistent) await this.persist();
      if (terminal) await this.discardSpool(entry);
    });
  } catch (persistError) {
    this.onError(persistError, entry.message);
    this.schedulePersistRetry(entry.message, terminal ? entry : undefined);
  }
  this.pump();

private async persist(): Promise<void> {
  const path = this.config.path;
  if (!path) return;
  const state: DeliveryStateFile = {
    version: 1,
    pending: this.pending
      .filter((entry) => entry.persistent)
      .map(({ persistent: _persistent, ...entry }) => {
        // Never write live attachments: JSON drops their `load()`, leaving a
        // record that claims attachments it cannot produce — and whose
        // presence would stop the loader from rehydrating from the spool.
        // `entry.spooled` is the durable representation.
        if (!entry.message.attachments?.length) return entry;
        const { attachments: _attachments, ...message } = entry.message;
        return { ...entry, message };
      }),
    completed: Object.fromEntries(this.completed),
  };
  const serialized = `${JSON.stringify(state)}\n`;
  if (Buffer.byteLength(serialized, "utf8") > MAX_DELIVERY_STATE_BYTES) {
    throw new DeliveryBackpressureError(this.config.maxPending);
  }
  const parent = dirname(path);
  await ensureRealDirectory(parent);
  await assertSafeRegularTarget(path);
  const temporary = `${path}.${process.pid}.${randomUUID()}.tmp`;
  try {
    await writeFile(temporary, serialized, { encoding: "utf-8", mode: 0o600, flag: "wx" });
    await rename(temporary, path);
    await chmod(path, 0o600).catch(() => undefined);
  } catch (error) {
    await rm(temporary, { force: true }).catch(() => undefined);
    throw error;
  }
}

private async withMutation<T>(operation: () => Promise<T>): Promise<T> {
  const previous = this.mutation;
  let release!: () => void;
  this.mutation = new Promise<void>((resolve) => {
    release = resolve;
  });
  await previous;
  try {
    return await operation();
  } finally {
    release();
  }
}

const queue = new DeliveryQueue(
  this.delivery,
  async (adapterId, message) => {
    const adapter = adapterById.get(adapterId);
    if (!adapter) {
      // A durable record survived a config change that removed its adapter.
      // Signal unroutable so the queue drops it instead of retrying forever.
      throw new UnroutableDeliveryError(`Chat adapter no longer exists: ${adapterId}`);
    }
    await this.dispatch(adapter, message);
  },
  this.onError,
);
this.queue = queue;
await queue.start();

const runners: Promise<void>[] = [];
for (const [adapterId, adapter] of adapterById) {
  const handler = (message: ChannelMessage) =>
    queue.enqueue(adapterId, message).then(() => undefined);
  if (isWebhookChannelAdapter(adapter)) webhooks.push({ adapter, handler });
  runners.push(this.superviseAdapter(adapterId, adapter, handler, ownedAbort.signal));
}
// Only bind the ingress host:port when a channel actually needs a webhook
// route. A polling-only config (e.g. Telegram/Discord) must not open an
// HTTP listener — doing so unexpectedly exposes a port and fails startup
// outright when that port is already taken.
if (webhooks.length > 0) {
  runners.push(
    new WebhookIngressServer(this.webhook, webhooks, () => this.healthSnapshot()).run(
      ownedAbort.signal,
    ),
  );
}
try {
  await Promise.all(runners);
} finally {
  ownedAbort.abort();
  queue.stop();
  this.queue = undefined;
  this.startedAt = undefined;
  signal.removeEventListener("abort", stopOwned);
}

const configPath = readConfigPath(args);
const config = loadGatewayConfig({ configPath });
const lease = acquireGatewayInstanceLock(config.runtime.lockPath, "code-shell-chat CLI");
const shutdown = new AbortController();
const stop = () => shutdown.abort();
process.once("SIGINT", stop);
process.once("SIGTERM", stop);
try {
  const desktop = new DesktopControlClient(config.desktop);
  const adapters = await Promise.all(
    config.channels.map((channel) =>
      createChannelAdapterAsync(channel, { discordCommands: CODE_SHELL_REMOTE_COMMANDS }),
    ),
  );
  const gateway = new ChatGateway({
    adapters,
    webhook: config.webhook,
    delivery: {
      path: config.runtime.inboxPath,
      maxPending: config.runtime.maxPending,
      maxConcurrent: config.runtime.maxConcurrent,
      maxPerTarget: Math.max(
        config.runtime.maxPerTarget,
        MIMI_MIN_CONCURRENT_MESSAGES_PER_TARGET,
      ),
    },
    adapterRestart: {
      baseMs: config.runtime.adapterRestartBaseMs,
      maxMs: config.runtime.adapterRestartMaxMs,
    },
  });

  const gatewayTask = gateway.run(shutdown.signal);
  const notificationTask = desktop.watchEvents(
    shutdown.signal,
    createDesktopNotificationHandler(adapters, config.notifications, {
      progressStore: new FileNotificationDeliveryProgressStore(
        notificationDeliveryProgressPath(config.runtime.eventCursorPath),
      ),
      authorizeTarget: ({ channel, target }) => {
        const current = loadGatewayConfig({ configPath });
        return current.channels.some(
          (configured) =>
            configured.channel === channel && configured.allowedTargetIds.includes(target),
        );
      },
    }),
    {
      checkpointPath: config.runtime.eventCursorPath,
      onError: (error) =>
        console.error(
          `[code-shell-chat] Desktop 通知等待重试：${error instanceof Error ? error.message : String(error)}`,
        ),
    },
  );
  await Promise.all([gatewayTask, notificationTask]);
} finally {
  shutdown.abort();
  process.off("SIGINT", stop);
  process.off("SIGTERM", stop);
  lease.release();
}

main().catch((error) => {
  console.error(`[code-shell-chat] ${error instanceof Error ? error.message : String(error)}`);
  process.exitCode = 1;
});

